-- Additive editorial catalog; never removes or rewrites user data.
SET NAMES utf8mb4;
START TRANSACTION;
INSERT INTO organizacoes(nome,tipo,descricao,contato_email,status)
SELECT 'Catálogo editorial RolêOut - Uberaba','OUTRO','Informações públicas reunidas pelo RolêOut. Não representa os locais nem seus responsáveis.','catalogo@roleout.invalid','APROVADA'
WHERE NOT EXISTS(SELECT 1 FROM organizacoes WHERE contato_email='catalogo@roleout.invalid' AND nome='Catálogo editorial RolêOut - Uberaba');
SET @org=(SELECT MIN(id) FROM organizacoes WHERE contato_email='catalogo@roleout.invalid' AND nome='Catálogo editorial RolêOut - Uberaba');
INSERT INTO locais(organizacao_id,nome,descricao,categoria,endereco,cidade,uf,latitude,longitude,status) SELECT @org,'Mercado Municipal de Uberaba','Mercado tradicional para conhecer produtos e sabores locais. Compras e consumo são pagos à parte. Cadastro editorial de local real; não é evento agendado. Horários e condições a confirmar. Visita sem consumo ou serviços incluídos. Posição aproximada. Fonte: https://visiteuberaba.com.br/locais/mercado-municipal/','Gastronomia','Praça Manoel Terra, 255 - Centro','Uberaba','MG',-19.751133,-47.931625,'PUBLICADO' WHERE @org IS NOT NULL AND NOT EXISTS(SELECT 1 FROM locais WHERE organizacao_id=@org AND nome='Mercado Municipal de Uberaba');
SET @venue=(SELECT MIN(id) FROM locais WHERE organizacao_id=@org AND nome='Mercado Municipal de Uberaba');
INSERT INTO roles(nome,descricao,local,cidade,categoria,valor,local_id) SELECT 'Mercado Municipal de Uberaba','Mercado tradicional para conhecer produtos e sabores locais. Compras e consumo são pagos à parte. Cadastro editorial de local real; não é evento agendado. Horários e condições a confirmar. Visita sem consumo ou serviços incluídos. Posição aproximada. Fonte: https://visiteuberaba.com.br/locais/mercado-municipal/','Praça Manoel Terra, 255 - Centro','Uberaba','Gastronomia',0,@venue WHERE @venue IS NOT NULL AND NOT EXISTS(SELECT 1 FROM roles WHERE local_id=@venue);
INSERT INTO locais(organizacao_id,nome,descricao,categoria,endereco,cidade,uf,latitude,longitude,status) SELECT @org,'Parque das Acácias (Piscinão)','Espaço público com área verde, pista de caminhada e equipamentos esportivos. Cadastro editorial de local real; não é evento agendado. Horários e condições a confirmar. Visita sem consumo ou serviços incluídos. Posição aproximada. Fonte: https://visiteuberaba.com.br/locais/parque-das-acacias/','Natureza','Av. Claricinda Alves de Rezende, 515','Uberaba','MG',-19.747845,-47.91372,'PUBLICADO' WHERE @org IS NOT NULL AND NOT EXISTS(SELECT 1 FROM locais WHERE organizacao_id=@org AND nome='Parque das Acácias (Piscinão)');
SET @venue=(SELECT MIN(id) FROM locais WHERE organizacao_id=@org AND nome='Parque das Acácias (Piscinão)');
INSERT INTO roles(nome,descricao,local,cidade,categoria,valor,local_id) SELECT 'Parque das Acácias (Piscinão)','Espaço público com área verde, pista de caminhada e equipamentos esportivos. Cadastro editorial de local real; não é evento agendado. Horários e condições a confirmar. Visita sem consumo ou serviços incluídos. Posição aproximada. Fonte: https://visiteuberaba.com.br/locais/parque-das-acacias/','Av. Claricinda Alves de Rezende, 515','Uberaba','Natureza',0,@venue WHERE @venue IS NOT NULL AND NOT EXISTS(SELECT 1 FROM roles WHERE local_id=@venue);
INSERT INTO locais(organizacao_id,nome,descricao,categoria,endereco,cidade,uf,latitude,longitude,status) SELECT @org,'Parque Municipal Mata do Ipê','Parque urbano arborizado com trilhas e lagos. Consulte as condições de acesso antes de visitar. Cadastro editorial de local real; não é evento agendado. Horários e condições a confirmar. Visita sem consumo ou serviços incluídos. Posição aproximada. Fonte: https://www.uberaba.mg.gov.br/portal/acervo/agua_viva/arquivos/avaliacao_ambiental/Relatorio%20Ambiental%202.pdf','Natureza','Av. Guilherme Ferreira com Av. Nelson Freire','Uberaba','MG',-19.762589,-47.935112,'PUBLICADO' WHERE @org IS NOT NULL AND NOT EXISTS(SELECT 1 FROM locais WHERE organizacao_id=@org AND nome='Parque Municipal Mata do Ipê');
SET @venue=(SELECT MIN(id) FROM locais WHERE organizacao_id=@org AND nome='Parque Municipal Mata do Ipê');
INSERT INTO roles(nome,descricao,local,cidade,categoria,valor,local_id) SELECT 'Parque Municipal Mata do Ipê','Parque urbano arborizado com trilhas e lagos. Consulte as condições de acesso antes de visitar. Cadastro editorial de local real; não é evento agendado. Horários e condições a confirmar. Visita sem consumo ou serviços incluídos. Posição aproximada. Fonte: https://www.uberaba.mg.gov.br/portal/acervo/agua_viva/arquivos/avaliacao_ambiental/Relatorio%20Ambiental%202.pdf','Av. Guilherme Ferreira com Av. Nelson Freire','Uberaba','Natureza',0,@venue WHERE @venue IS NOT NULL AND NOT EXISTS(SELECT 1 FROM roles WHERE local_id=@venue);
COMMIT;
SELECT COUNT(*) AS locais_editoriais FROM locais WHERE organizacao_id=@org;
